Autenticidad.ejemplo:
import hmac, hashlib
def verify_webhook(secret: bytes, body: bytes, sig_header: str) -> bool:
    expected = "sha256=" + hmac.new(secret, body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, sig_header)

Control preventivo.ejemplo:
# Política preventiva en Kubernetes (Kyverno) contra contenedores root
apiVersion: kyverno.io/v1
kind: ClusterPolicy
metadata: { name: require-non-root }
spec:
  validationFailureAction: Enforce
  rules:
    - name: check-runasnonroot
      match: { any: [{ resources: { kinds: ["Pod"] } }] }
      validate: { pattern: { spec: { securityContext: { runAsNonRoot: true } } } }

